-- Letters of recommendation: one per enrolment, only after its certificate has been generated.
-- Generated by an admin or the student's tutor; the body is written by the system from the course and can be
-- edited by admins/superadmins only. Public check: verify/?reg=<registration no> (or the letter's own key).
CREATE TABLE IF NOT EXISTS recommendation_letters (
    id INT AUTO_INCREMENT PRIMARY KEY,
    registration_id INT NOT NULL,
    certificate_id INT NOT NULL,
    body TEXT NOT NULL,
    verify_hash CHAR(32) NOT NULL,
    created_by INT NULL,
    edited_by INT NULL,
    edited_at TIMESTAMP NULL DEFAULT NULL,
    emailed_at TIMESTAMP NULL DEFAULT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_lor_registration (registration_id),
    UNIQUE KEY uq_lor_hash (verify_hash),
    KEY idx_lor_certificate (certificate_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
